#include <bits/stdc++.h>
using namespace std;
const long long MOD = 1000000007;

int main() {
    string s;
    int n, x, y;
    cin >> s >> n >> x >> y;
    if (x > n || y > n) {
        cout << 0 << "\n";
        return 0;
    }
    // f[p]: distinct valid strings (empty included) ending at p; last[d]: what the previous same letter added.
    vector<long long> f(n + 1), added(n + 1);
    vector<vector<long long>> last(2, vector<long long>(n + 1));
    f[x] = 1;
    for (char ch : s) {
        int d = ch == 'r';
        for (int j = 0; j <= n; j++) {
            int from = d ? j - 1 : j + 1;
            added[j] = from >= 0 && from <= n ? f[from] : 0;
        }
        for (int j = 0; j <= n; j++) f[j] = ((f[j] + added[j] - last[d][j]) % MOD + MOD) % MOD;
        last[d] = added;
    }
    cout << f[y] << "\n";
}

import java.io.*;
import java.util.*;

public class Main {
    static final InputStream IN = System.in;
    static final byte[] BUF = new byte[1 << 16];
    static int len, ptr;

    static int readByte() throws IOException {
        if (ptr == len) {
            len = IN.read(BUF, 0, BUF.length);
            ptr = 0;
            if (len <= 0) {
                len = 0;
                return -1;
            }
        }
        return BUF[ptr++];
    }

    static long nextLong() throws IOException {
        int c = readByte();
        while (c == ' ' || c == '\n' || c == '\r' || c == '\t') c = readByte();
        boolean neg = c == '-';
        if (neg) c = readByte();
        long v = 0;
        while (c >= '0' && c <= '9') {
            v = v * 10 + (c - '0');
            c = readByte();
        }
        return neg ? -v : v;
    }

    static int nextInt() throws IOException {
        return (int) nextLong();
    }

    static String next() throws IOException {
        int c = readByte();
        while (c == ' ' || c == '\n' || c == '\r' || c == '\t') c = readByte();
        StringBuilder sb = new StringBuilder();
        while (c > ' ') {
            sb.append((char) c);
            c = readByte();
        }
        return sb.toString();
    }

    public static void main(String[] args) throws IOException {
        final long MOD = 1000000007;
        String s = next();
        int n = nextInt(), x = nextInt(), y = nextInt();
        if (x > n || y > n) {
            System.out.println(0);
            return;
        }
        long[] f = new long[n + 1];
        long[][] last = new long[2][n + 1];
        f[x] = 1;
        for (int k = 0; k < s.length(); k++) {
            int d = s.charAt(k) == 'r' ? 1 : 0;
            long[] added = new long[n + 1];
            for (int j = 0; j <= n; j++) {
                int from = d == 1 ? j - 1 : j + 1;
                added[j] = from >= 0 && from <= n ? f[from] : 0;
            }
            for (int j = 0; j <= n; j++) f[j] = Math.floorMod(f[j] + added[j] - last[d][j], MOD);
            last[d] = added;
        }
        System.out.println(f[y]);
    }
}

package main

import (
	"fmt"
	"io"
	"os"
)

var data []byte
var pos int

// token returns the next whitespace-separated token of stdin.
func token() []byte {
	for pos < len(data) && data[pos] <= ' ' {
		pos++
	}
	start := pos
	for pos < len(data) && data[pos] > ' ' {
		pos++
	}
	return data[start:pos]
}

func nextInt() int {
	b := token()
	neg := len(b) > 0 && b[0] == '-'
	if neg {
		b = b[1:]
	}
	v := 0
	for _, c := range b {
		v = v*10 + int(c-'0')
	}
	if neg {
		return -v
	}
	return v
}

func main() {
	const MOD = 1000000007
	data, _ = io.ReadAll(os.Stdin)
	s := token()
	n, x, y := nextInt(), nextInt(), nextInt()
	if x > n || y > n {
		fmt.Println(0)
		return
	}
	f := make([]int, n+1)
	last := [2][]int{make([]int, n+1), make([]int, n+1)}
	f[x] = 1
	for _, ch := range s {
		d := 0
		if ch == 'r' {
			d = 1
		}
		added := make([]int, n+1)
		for j := 0; j <= n; j++ {
			from := j + 1
			if d == 1 {
				from = j - 1
			}
			if from >= 0 && from <= n {
				added[j] = f[from]
			}
		}
		for j := 0; j <= n; j++ {
			f[j] = ((f[j]+added[j]-last[d][j])%MOD + MOD) % MOD
		}
		last[d] = added
	}
	fmt.Println(f[y])
}
